import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;

/// Where tool/bundle_shell.dart writes, relative to the CLI package.
const String bundleOutputPath = 'lib/src/generated/shell_bundle.g.dart';
const String devicesOutputPath = 'lib/src/generated/devices.g.dart';

const String _header = '// GENERATED by tool/bundle_shell.dart from packages/iphonesim_shell/lib.\n'
    '// Do not edit. Regenerate with: dart run tool/bundle_shell.dart\n';

/// All `.dart` files under [shellLib], keyed by their path relative to it.
Map<String, String> readShellSources(Directory shellLib) {
  final files = shellLib
      .listSync(recursive: true)
      .whereType<File>()
      .where((file) => file.path.endsWith('.dart'))
      .toList()
    ..sort((a, b) => a.path.compareTo(b.path));
  return <String, String>{
    for (final file in files)
      p.posix.joinAll(p.split(p.relative(file.path, from: shellLib.path))): file.readAsStringSync(),
  };
}

/// The shell sources as a Dart map literal (base64, so no escaping issues).
String renderBundle(Directory shellLib) {
  final buffer = StringBuffer(_header)
    ..writeln()
    ..writeln('const Map<String, String> shellBundle = <String, String>{');
  readShellSources(shellLib).forEach((path, source) {
    buffer.writeln("  '$path': '${base64.encode(utf8.encode(source))}',");
  });
  buffer.writeln('};');
  return buffer.toString();
}

/// A copy of the shell's device table, so the CLI can list and validate
/// devices without depending on Flutter.
String renderDevices(Directory shellLib) {
  final source = File(p.join(shellLib.path, 'src', 'devices.dart')).readAsStringSync();
  return '$_header\n$source';
}
